// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {Hooks} from "v4-core/src/libraries/Hooks.sol";
import {PegFeeHook} from "src/PegFeeHook.sol";

/// @dev What the admission floor (Hook.protected.t.sol) asks every hook: not part of IHooks, so a hook that
/// omits it still trades, but the floor cannot admit it.
interface IHookPermissions {
    function getHookPermissions() external pure returns (Hooks.Permissions memory);
}

/// @notice PegFeeHook does not implement getHookPermissions(); the call reverts, and with it the floor's
/// test_permissionsMatchTheDeclaredFlags and test_callbacksRefuseCallersOtherThanThePoolManager.
/// Fails on the current code (the call reverts). Passes once the hook declares the permissions its address
/// carries: beforeInitialize and beforeSwap true, everything else false.
contract PegFeeHookPermissionsTest is Test {
    IPoolManager pm;
    PegFeeHook hook;

    function setUp() public {
        pm = IPoolManager(address(0xBEEF)); // the hook only stores it; nothing here swaps
        address stable = address(0x1000);
        address quote = address(0x2000);
        bytes memory init =
            abi.encodePacked(type(PegFeeHook).creationCode, abi.encode(pm, stable, uint8(18), quote, uint8(6)));
        bytes32 initHash = keccak256(init);
        uint160 flags = Hooks.BEFORE_INITIALIZE_FLAG | Hooks.BEFORE_SWAP_FLAG;
        for (uint256 salt;; ++salt) {
            address a = vm.computeCreate2Address(bytes32(salt), initHash, address(this));
            if (uint160(a) & Hooks.ALL_HOOK_MASK == flags) {
                hook = new PegFeeHook{salt: bytes32(salt)}(pm, stable, 18, quote, 6);
                require(address(hook) == a);
                break;
            }
        }
    }

    function test_declaresThePermissionsItsAddressCarries() public view {
        (bool ok, bytes memory ret) = address(hook).staticcall(abi.encodeCall(IHookPermissions.getHookPermissions, ()));
        assertTrue(ok, "getHookPermissions() reverts: the hook does not declare its permissions");
        assertEq(ret.length, 14 * 32, "getHookPermissions() must return Hooks.Permissions (14 bools)");
        Hooks.Permissions memory p = abi.decode(ret, (Hooks.Permissions));

        uint160 implemented;
        if (p.beforeInitialize) implemented |= Hooks.BEFORE_INITIALIZE_FLAG;
        if (p.afterInitialize) implemented |= Hooks.AFTER_INITIALIZE_FLAG;
        if (p.beforeAddLiquidity) implemented |= Hooks.BEFORE_ADD_LIQUIDITY_FLAG;
        if (p.afterAddLiquidity) implemented |= Hooks.AFTER_ADD_LIQUIDITY_FLAG;
        if (p.beforeRemoveLiquidity) implemented |= Hooks.BEFORE_REMOVE_LIQUIDITY_FLAG;
        if (p.afterRemoveLiquidity) implemented |= Hooks.AFTER_REMOVE_LIQUIDITY_FLAG;
        if (p.beforeSwap) implemented |= Hooks.BEFORE_SWAP_FLAG;
        if (p.afterSwap) implemented |= Hooks.AFTER_SWAP_FLAG;
        if (p.beforeDonate) implemented |= Hooks.BEFORE_DONATE_FLAG;
        if (p.afterDonate) implemented |= Hooks.AFTER_DONATE_FLAG;
        if (p.beforeSwapReturnDelta) implemented |= Hooks.BEFORE_SWAP_RETURNS_DELTA_FLAG;
        if (p.afterSwapReturnDelta) implemented |= Hooks.AFTER_SWAP_RETURNS_DELTA_FLAG;
        if (p.afterAddLiquidityReturnDelta) implemented |= Hooks.AFTER_ADD_LIQUIDITY_RETURNS_DELTA_FLAG;
        if (p.afterRemoveLiquidityReturnDelta) implemented |= Hooks.AFTER_REMOVE_LIQUIDITY_RETURNS_DELTA_FLAG;

        assertEq(implemented, uint160(address(hook)) & Hooks.ALL_HOOK_MASK, "declared permissions differ from the address bits");
        assertEq(implemented, Hooks.BEFORE_INITIALIZE_FLAG | Hooks.BEFORE_SWAP_FLAG);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {Hooks} from "v4-core/src/libraries/Hooks.sol";
import {PegFeeHook} from "src/PegFeeHook.sol";

/// @notice The network's hook admission floor asks every hook `getHookPermissions()` and compares the answer with
/// the flag bits of the mined address. PegFeeHook has no such function: the call reverts, and with it the floor's
/// permission and caller-refusal checks.
contract PegFeeHookPermissionsTest is Test {
    address constant POOL_MANAGER = 0x000000000004444c5dc75cB358380D2e3dE08A90;
    address constant IMDUSD = 0x1000000000000000000000000000000000000001;
    address constant USDC = 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48;

    PegFeeHook hook;

    function setUp() public {
        uint160[4] memory candidates = [
            Hooks.BEFORE_INITIALIZE_FLAG | Hooks.BEFORE_SWAP_FLAG,
            Hooks.BEFORE_INITIALIZE_FLAG | Hooks.BEFORE_SWAP_FLAG | Hooks.AFTER_SWAP_FLAG,
            Hooks.BEFORE_INITIALIZE_FLAG | Hooks.BEFORE_SWAP_FLAG | Hooks.AFTER_SWAP_FLAG | Hooks.AFTER_SWAP_RETURNS_DELTA_FLAG,
            Hooks.BEFORE_INITIALIZE_FLAG | Hooks.BEFORE_SWAP_FLAG | Hooks.BEFORE_SWAP_RETURNS_DELTA_FLAG
        ];
        bytes32 initHash = keccak256(
            abi.encodePacked(
                type(PegFeeHook).creationCode, abi.encode(IPoolManager(POOL_MANAGER), IMDUSD, uint8(18), USDC, uint8(6))
            )
        );
        for (uint256 c; c < candidates.length && address(hook) == address(0); ++c) {
            for (uint256 salt;; ++salt) {
                address a = vm.computeCreate2Address(bytes32(salt), initHash, address(this));
                if (uint160(a) & Hooks.ALL_HOOK_MASK != candidates[c]) continue;
                try new PegFeeHook{salt: bytes32(salt)}(IPoolManager(POOL_MANAGER), IMDUSD, 18, USDC, 6) returns (
                    PegFeeHook deployed
                ) {
                    hook = deployed;
                } catch {}
                break;
            }
        }
        require(address(hook) != address(0), "could not place the hook on an address it accepts");
    }

    function test_getHookPermissionsAnswersAndMatchesTheAddress() public {
        (bool ok, bytes memory ret) = address(hook).call(abi.encodeWithSignature("getHookPermissions()"));
        assertTrue(ok, "getHookPermissions() reverts: the admission floor cannot read the hook's permissions");
        Hooks.Permissions memory p = abi.decode(ret, (Hooks.Permissions));

        uint160 implemented;
        if (p.beforeInitialize) implemented |= Hooks.BEFORE_INITIALIZE_FLAG;
        if (p.afterInitialize) implemented |= Hooks.AFTER_INITIALIZE_FLAG;
        if (p.beforeAddLiquidity) implemented |= Hooks.BEFORE_ADD_LIQUIDITY_FLAG;
        if (p.afterAddLiquidity) implemented |= Hooks.AFTER_ADD_LIQUIDITY_FLAG;
        if (p.beforeRemoveLiquidity) implemented |= Hooks.BEFORE_REMOVE_LIQUIDITY_FLAG;
        if (p.afterRemoveLiquidity) implemented |= Hooks.AFTER_REMOVE_LIQUIDITY_FLAG;
        if (p.beforeSwap) implemented |= Hooks.BEFORE_SWAP_FLAG;
        if (p.afterSwap) implemented |= Hooks.AFTER_SWAP_FLAG;
        if (p.beforeDonate) implemented |= Hooks.BEFORE_DONATE_FLAG;
        if (p.afterDonate) implemented |= Hooks.AFTER_DONATE_FLAG;
        if (p.beforeSwapReturnDelta) implemented |= Hooks.BEFORE_SWAP_RETURNS_DELTA_FLAG;
        if (p.afterSwapReturnDelta) implemented |= Hooks.AFTER_SWAP_RETURNS_DELTA_FLAG;
        if (p.afterAddLiquidityReturnDelta) implemented |= Hooks.AFTER_ADD_LIQUIDITY_RETURNS_DELTA_FLAG;
        if (p.afterRemoveLiquidityReturnDelta) implemented |= Hooks.AFTER_REMOVE_LIQUIDITY_RETURNS_DELTA_FLAG;

        assertTrue(p.beforeInitialize, "a launch hook needs an initialization callback");
        assertEq(implemented, uint160(address(hook)) & Hooks.ALL_HOOK_MASK, "permissions disagree with the address");
    }
}

