// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {IHooks} from "v4-core/src/interfaces/IHooks.sol";
import {PoolKey} from "v4-core/src/types/PoolKey.sol";
import {Currency} from "v4-core/src/types/Currency.sol";
import {BeforeSwapDelta} from "v4-core/src/types/BeforeSwapDelta.sol";
import {SwapParams} from "v4-core/src/types/PoolOperation.sol";
import {LPFeeLibrary} from "v4-core/src/libraries/LPFeeLibrary.sol";
import {TickMath} from "v4-core/src/libraries/TickMath.sol";
import {Hooks} from "v4-core/src/libraries/Hooks.sol";
import {PegFeeHook} from "src/PegFeeHook.sol";

/// @dev Stands in for the PoolManager: the hook only reads slot0 through extsload, so answering that call with a
/// chosen sqrtPrice reproduces exactly what the hook sees before each swap. (The repository's v4-core copy has no
/// solmate, so the real PoolManager cannot be compiled here.)
contract FakeManager {
    bytes32 word;

    function set(uint160 sqrtPriceX96) external {
        word = bytes32(uint256(sqrtPriceX96));
    }

    function extsload(bytes32) external view returns (bytes32) {
        return word;
    }
}

/// @notice The escalated fee is decided from the pre-swap price only, so it is bypassed by (1) pulling the price
/// into the ±0.25% band with a floor-fee "towards" swap and then dumping any size in one floor-fee swap, or (2) a
/// single "towards" swap whose limit lies far beyond the peg on the other side. Both legs below are what the
/// PoolManager would charge; the expected values are the cap, which is what the trade's destination warrants.
contract FeeBypassProofTest is Test {
    FakeManager pm;
    address imdUsd = address(0x1000); // token0 (18 decimals), as the constructor is told
    address usdc = address(0x2000); // token1 (6 decimals)
    PegFeeHook hook;
    PoolKey key;

    function setUp() public {
        pm = new FakeManager();
        bytes memory init = abi.encodePacked(
            type(PegFeeHook).creationCode, abi.encode(address(pm), imdUsd, uint8(18), usdc, uint8(6))
        );
        bytes32 initHash = keccak256(init);
        uint160 flags = Hooks.BEFORE_INITIALIZE_FLAG | Hooks.BEFORE_SWAP_FLAG;
        for (uint256 salt;; ++salt) {
            address a = vm.computeCreate2Address(bytes32(salt), initHash, address(this));
            if (uint160(a) & Hooks.ALL_HOOK_MASK == flags) {
                hook = new PegFeeHook{salt: bytes32(salt)}(IPoolManager(address(pm)), imdUsd, 18, usdc, 6);
                require(address(hook) == a);
                break;
            }
        }
        key = PoolKey(Currency.wrap(imdUsd), Currency.wrap(usdc), LPFeeLibrary.DYNAMIC_FEE_FLAG, 1, IHooks(address(hook)));
    }

    function _sqrt(uint256 x) internal pure returns (uint256 y) {
        y = x;
        uint256 z = (x + 1) / 2;
        while (z < y) (y, z) = (z, (x / z + z) / 2);
    }

    /// sqrtPriceX96 at which imdUSD is worth `priceE18` USDC (1e18 = $1)
    function _sqrtFor(uint256 priceE18) internal view returns (uint160) {
        return uint160(uint256(hook.pegSqrtPriceX96()) * _sqrt(priceE18 * 1e18) / 1e18);
    }

    /// The LP fee the PoolManager applies to a swap in `zeroForOne` with limit `limit`, pool at `pre`.
    function _fee(uint160 pre, bool zeroForOne, uint160 limit) internal returns (uint24) {
        pm.set(pre);
        vm.prank(address(pm));
        (bytes4 sel, BeforeSwapDelta d, uint24 f) =
            hook.beforeSwap(address(0xBEEF), key, SwapParams(zeroForOne, -1_000_000e18, limit), "");
        assertEq(sel, IHooks.beforeSwap.selector);
        assertEq(BeforeSwapDelta.unwrap(d), 0);
        assertTrue(f & LPFeeLibrary.OVERRIDE_FEE_FLAG != 0, "override flag");
        return f & ~LPFeeLibrary.OVERRIDE_FEE_FLAG;
    }

    /// Pool at $0.98. A direct dump of imdUSD pays the 5% cap. Pulling the price to $0.9976 first (buying imdUSD,
    /// "towards", floor fee) and then dumping everything with an unbounded limit pays the floor on the dump too.
    function test_pullIntoBandThenDumpPaysTheFloor() public {
        uint160 at098 = _sqrtFor(0.9799e18);
        assertEq(_fee(at098, true, TickMath.MIN_SQRT_PRICE + 1), hook.MAX_FEE(), "direct dump at $0.98 pays the cap");

        // leg 1: buy imdUSD with a limit at the band's edge: towards the peg, floor fee (fine)
        uint160 bandEdge = _sqrtFor(0.9976e18);
        assertEq(_fee(at098, false, bandEdge), hook.BASE_FEE(), "pull-back pays the floor");

        // leg 2: the pool now sits at $0.9976; dump with the limit at the bottom of the range
        uint24 dumpFee = _fee(bandEdge, true, TickMath.MIN_SQRT_PRICE + 1);
        assertGe(dumpFee, hook.MAX_FEE(), "a dump allowed to run below $0.98 must pay the cap");
    }

    /// Pool at $0.98. One swap buying imdUSD with its limit at $1.10 is "towards" at its start and ends 10% above
    /// the peg: it pays the floor for the whole path, including the part from $1.0025 to $1.10.
    function test_crossThroughPaysTheFloor() public {
        uint24 fee = _fee(_sqrtFor(0.9799e18), false, _sqrtFor(1.10e18));
        assertGe(fee, hook.MAX_FEE(), "a swap whose limit is 10% above the peg must pay the cap");
    }
}

