/// @dev What the admission floor (Hook.protected.t.sol) asks every hook: the permissions it implements, so they
/// can be compared with the bits its address was mined for.
interface IHookPermissions {
    function getHookPermissions() external pure returns (Hooks.Permissions memory);
}

contract HookPermissionsProofTest is Test {
    PegFeeHook hook;

    function setUp() public {
        address pm = address(0x4444);
        address imdUsd = address(0x1000);
        address usdc = address(0x2000);
        bytes memory init =
            abi.encodePacked(type(PegFeeHook).creationCode, abi.encode(pm, imdUsd, uint8(18), usdc, uint8(6)));
