                require(address(hook) == a);
                break;
            }
        }
    }

    /// The hook must report its permissions, and they must be exactly the two bits its address carries.
    function test_getHookPermissionsMatchesTheAddress() public view {
        Hooks.Permissions memory p = IHookPermissions(address(hook)).getHookPermissions();
        uint160 implemented;
